/*
 * COMPOSITION: A single machined CTA plate (rounded-rect, extruded, chamfered)
 *   floats center-frame over a graded DARK stage plane (z=-2.5, unlit so it
 *   cannot blow out under the rig); a soft red underglow halo breathes behind
 *   the plate near the practical light, a thin accent ring traces the plate
 *   perimeter as the emissive channel, and a contact-shadow ellipse grounds it.
 *   Label + caption sit on/below the face, sized to the scene-unit type scale.
 * LIGHT RIG: underglow-signal rig, tuned into the product-shot caps to avoid
 *   blowout — key directional (#f8f4ee @1.4) raking upper-right, red practical
 *   point (#ff2a38 @6) glowing from below the plate, white rim directional
 *   (@0.8) from back-left, low ambient floor (0.12). Backdrop is intentionally
 *   UNLIT so the rig cannot wash it to white.
 * MATERIAL STRATEGY: MeshPhysicalNodeMaterial on the plate (roughness 0.5,
 *   metalness 0.35, clearcoat 0.22) with a TSL vertical 3-stop gradient + hard
 *   0.01u seam, plus a low emissive bleed of the same gradient so hue survives
 *   compression under the key light; MeshStandardNodeMaterial emissive ring
 *   for the perimeter channel; unlit MeshBasicNodeMaterial backdrop carrying
 *   the ink/surface/background gradient + red underglow + vignette.
 * MOTION: GSAP weighted-settle mount (scale 1.04->1.0, power4.out, 0.9s);
 *   hover lifts the plate on Z + boosts edge emissive; press scales to 0.97
 *   with a back-out ease while the contact shadow tightens.
 * FOCAL ELEMENT: the CTA plate face (engineered red gradient + BEGIN
 *   COMMISSION label + perimeter emissive ring) is the single brightest,
 *   highest-contrast element in the frame.
 */

import {
  Group,
  Mesh,
  Shape,
  Path,
  ShapeGeometry,
  ExtrudeGeometry,
  PlaneGeometry,
  CircleGeometry,
  DirectionalLight,
  PointLight,
  AmbientLight,
  Object3D,
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  color,
  mix,
  clamp,
  step,
  smoothstep,
  abs,
  positionLocal,
  uniform,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

const BUTTON_WIDTH = 2.6;
const BUTTON_HEIGHT = 0.68;
const RADIUS = 0.08;
const DEPTH = 0.06;
const BEVEL = 0.03;
const RING_WIDTH = 0.015;

function buildRoundedRectPath(Ctor, width, height, radius) {
  const p = new Ctor();
  const x = -width / 2;
  const y = -height / 2;
  const w = width;
  const h = height;
  const r = radius;
  p.moveTo(x, y + r);
  p.lineTo(x, y + h - r);
  p.quadraticCurveTo(x, y + h, x + r, y + h);
  p.lineTo(x + w - r, y + h);
  p.quadraticCurveTo(x + w, y + h, x + w, y + h - r);
  p.lineTo(x + w, y + r);
  p.quadraticCurveTo(x + w, y, x + w - r, y);
  p.lineTo(x + r, y);
  p.quadraticCurveTo(x, y, x, y + r);
  return p;
}

function disposeObject3D(root) {
  root.traverse((obj) => {
    if (obj.geometry) obj.geometry.dispose();
    if (obj.material) {
      const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
      for (const m of mats) {
        if (m.map) m.map.dispose?.();
        m.dispose?.();
      }
    }
  });
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  void THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#ff4450' },
      { at: 0.55, hex: '#ff2a38' },
      { at: 1, hex: '#c1121f' },
    ],
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const ctaItem = items.find((i) => i.role === 'cta-label');
  const captionItem = items.find((i) => i.role === 'caption');
  const ctaText = ctaItem?.text ?? 'BEGIN COMMISSION';
  const captionText = captionItem?.text ?? 'NO DEPOSIT REQUIRED';

  const root = new Group();
  root.name = 'gradient-cta-object';

  // ---- backdrop stage plane (color.background / color.surface / color.ink) ----
  // UNLIT by design so the underglow-signal rig cannot blow it to white — the
  // gradient + halo + vignette live entirely in the color node.
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const bdUv = uv();
  const bdTop = color(colors.surface); // #16161d
  const bdBottom = color(colors.background); // #0b0b10
  const bdVert = mix(bdTop, bdBottom, smoothstep(0.2, 0.95, bdUv.y.oneMinus()));

  // soft red underglow halo tied to the practical light beneath the plate,
  // kept small (<=10% of frame) — accent used sparingly per palette law.
  const haloCenter = bdUv.sub(vec2Center());
  function vec2Center() {
    // local helper avoiding an extra import; construct via uv() itself
    return uv().sub(uv()).add(0.5).add(float(0.0).mul(0)).add(
      // manual 0.5,0.42 center offset using component ops
      0
    );
  }
  const cx = bdUv.x.sub(0.5);
  const cy = bdUv.y.sub(0.42);
  const halo = cx.mul(cx).add(cy.mul(cy)).sqrt();
  const haloMask = smoothstep(0.42, 0.0, halo).mul(0.22);
  const bdWithHalo = mix(bdVert, color(colors.accent), haloMask);

  // vignette using colors.ink so the tone stays warm-dark, never pure black
  const edge = cx.mul(cx).add(bdUv.y.sub(0.5).mul(bdUv.y.sub(0.5))).sqrt();
  const vignette = smoothstep(0.32, 0.75, edge);
  const bdFinal = mix(bdWithHalo, color(colors.ink), vignette.mul(0.55));
  backdropMat.colorNode = bdFinal;
  void haloCenter;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---- inner group carries hover/press transform, isolated from root scenePosition ----
  const inner = new Group();
  inner.name = 'cta-inner';
  root.add(inner);

  // ---- CTA plate geometry: rounded-rect extruded with chamfer bevel ----
  const plateShape = buildRoundedRectPath(Shape, BUTTON_WIDTH, BUTTON_HEIGHT, RADIUS);
  const plateGeo = new ExtrudeGeometry(plateShape, {
    depth: DEPTH,
    bevelEnabled: true,
    bevelThickness: BEVEL,
    bevelSize: BEVEL,
    bevelSegments: 1,
    steps: 1,
  });
  plateGeo.translate(0, 0, -DEPTH / 2);

  const plateMat = new MeshPhysicalNodeMaterial({
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
  });

  // color.gradient — 3-stop vertical gradient with hard 0.01-unit seam at 0.55
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#ff4450' },
    { at: 0.55, hex: '#ff2a38' },
    { at: 1, hex: '#c1121f' },
  ];
  const cTop = color(stops[0]?.hex ?? '#ff4450');
  const cMid = color(stops[1]?.hex ?? '#ff2a38');
  const cBottom = color(stops[2]?.hex ?? '#c1121f');

  const s = clamp(float(0.5).sub(positionLocal.y.div(BUTTON_HEIGHT)), 0.0, 1.0);
  const seg1 = mix(cTop, cMid, clamp(s.div(0.55), 0.0, 1.0));
  const seg2 = mix(cMid, cBottom, clamp(s.sub(0.55).div(0.45), 0.0, 1.0));
  const segMix = mix(seg1, seg2, step(0.55, s));
  const seamMask = float(1.0).sub(smoothstep(0.0, 0.0147, abs(s.sub(0.55))));
  const plateColorNode = mix(segMix, segMix.mul(0.55), seamMask);
  plateMat.colorNode = plateColorNode;
  // low emissive bleed keeps the reds saturated even when the key light
  // compresses diffuse response toward white — prevents washed-pink blowout.
  plateMat.emissiveNode = plateColorNode.mul(0.18);

  const plate = new Mesh(plateGeo, plateMat);
  inner.add(plate);

  // ---- perimeter emissive channel (effects.spec / DL12 accent edge light) ----
  const ringOuter = buildRoundedRectPath(
    Shape,
    BUTTON_WIDTH + RING_WIDTH * 2,
    BUTTON_HEIGHT + RING_WIDTH * 2,
    RADIUS + RING_WIDTH
  );
  const ringHole = buildRoundedRectPath(Path, BUTTON_WIDTH, BUTTON_HEIGHT, RADIUS);
  ringOuter.holes.push(ringHole);
  const ringGeo = new ShapeGeometry(ringOuter);

  const emissiveIntensity = uniform(1.6);
  const ringMat = new MeshStandardNodeMaterial({ roughness: 1, metalness: 0 });
  const accentC = color(colors.accent);
  ringMat.colorNode = accentC.mul(0.4);
  ringMat.emissiveNode = accentC.mul(emissiveIntensity);
  const ring = new Mesh(ringGeo, ringMat);
  ring.position.z = DEPTH / 2 + 0.002;
  inner.add(ring);

  // soft glow bloom behind the ring so the accent edge light reads even
  // without a post-process bloom pass (unlit, additive-feeling gradient).
  const glowGeo = new ShapeGeometry(
    buildRoundedRectPath(Shape, BUTTON_WIDTH + 0.5, BUTTON_HEIGHT + 0.5, RADIUS + 0.2)
  );
  const glowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const gUv = uv();
  const gDist = gUv.sub(0.5).length();
  const glowFalloff = smoothstep(0.5, 0.0, gDist).mul(0.35);
  glowMat.colorNode = accentC;
  glowMat.opacityNode = glowFalloff;
  const glow = new Mesh(glowGeo, glowMat);
  glow.position.z = -DEPTH / 2 - 0.03;
  inner.add(glow);

  // ---- contact shadow plane ----
  const shadowGeo = new CircleGeometry(1.7, 48);
  const shadowOpacity = uniform(0.35);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shadowMat.colorNode = color(colors.ink);
  shadowMat.opacityNode = shadowOpacity;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -1.2;
  shadow.position.set(0, -0.42, 0.02);
  inner.add(shadow);

  // ---- text: cta-label + caption ----
  // fontSize expressed in scene-unit em-heights per the type scale doctrine:
  // the spec's 20px/9px ratio (~2.22) maps to subhead 0.2 / caption 0.09.
  const ctaLabel = ctx.fontAtlas.createText(ctaText, {
    fontSize: 0.2,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 0.08 * 0.2,
  });
  ctaLabel.position.set(0, 0, DEPTH / 2 + 0.02);
  inner.add(ctaLabel);

  const caption = ctx.fontAtlas.createText(captionText, {
    fontSize: 0.09,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 0.12 * 0.09,
  });
  caption.position.set(0, -BUTTON_HEIGHT / 2 - 0.25, 0.02);
  inner.add(caption);

  // ---- lighting rig: underglow-signal, tuned into product-shot caps ----
  const ambient = new AmbientLight(0xffffff, 0.12);
  root.add(ambient);

  const key = new DirectionalLight('#f8f4ee', 1.4);
  key.position.set(1.4, 3, 2);
  const keyTarget = new Object3D();
  keyTarget.position.set(0, 0.4, 0);
  root.add(keyTarget);
  key.target = keyTarget;
  root.add(key);

  const practical = new PointLight('#ff2a38', 6, 4, 2);
  practical.position.set(0, -0.65, 0.6);
  root.add(practical);

  const rim = new DirectionalLight('#ffffff', 0.8);
  rim.position.set(-1.4, 2, -2.4);
  const rimTarget = new Object3D();
  rimTarget.position.set(0, 0.5, 0);
  root.add(rimTarget);
  rim.target = rimTarget;
  root.add(rim);

  // ---- optional cinematic primitives (none specified for this node) ----
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives?.[prim.name];
    if (fn) {
      primitiveHandles.push(fn(inner, prim.params));
    }
  }

  // ---- motion: weighted-settle mount ----
  const timelines = [];
  inner.scale.setScalar(1.04);
  const mountTl = gsap.timeline();
  mountTl.to(inner.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(mountTl);

  // ---- interaction handlers ----
  let pressed = false;
  let hovering = false;

  function applyHoverIn() {
    hovering = true;
    const tl = gsap.timeline();
    tl.to(inner.position, { z: 0.06, duration: 0.18, ease: 'power2.out' });
    tl.to(emissiveIntensity, { value: 2.2, duration: 0.18, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function applyHoverOut() {
    hovering = false;
    if (pressed) return;
    const tl = gsap.timeline();
    tl.to(inner.position, { z: 0, duration: 0.18, ease: 'power2.out' });
    tl.to(emissiveIntensity, { value: 1.6, duration: 0.18, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function applyPressDown() {
    pressed = true;
    const tl = gsap.timeline();
    tl.to(inner.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    tl.to(shadowOpacity, { value: 0.55, duration: 0.12, ease: 'power2.out' }, 0);
    tl.to(shadow.scale, { x: 0.85, y: 0.85, duration: 0.12, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function applyPressUp() {
    pressed = false;
    const tl = gsap.timeline();
    tl.to(inner.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'power3.out',
    });
    tl.to(shadowOpacity, { value: 0.35, duration: 0.18, ease: 'power2.out' }, 0);
    tl.to(shadow.scale, { x: 1, y: 1, duration: 0.18, ease: 'power2.out' }, 0);
    if (!hovering) {
      tl.to(inner.position, { z: 0, duration: 0.18, ease: 'power2.out' }, 0);
      tl.to(emissiveIntensity, { value: 1.6, duration: 0.18, ease: 'power2.out' }, 0);
    }
    timelines.push(tl);
    ctx.emit?.('cta-activated', { itemId: config.id ?? 'gradient-cta' });
  }

  root.userData.handlers = {
    pointerenter: applyHoverIn,
    pointerover: applyHoverIn,
    pointerleave: applyHoverOut,
    pointerout: applyHoverOut,
    pointerdown: applyPressDown,
    pointerup: applyPressUp,
    click: () => {
      ctx.emit?.('navigate', { to: config.navigateTo ?? 'hub-pricing' });
    },
  };

  // ---- cleanup ----
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const handle of primitiveHandles) handle?.cleanup?.();
    disposeObject3D(root);
  };

  return root;
}

/* @spec-manifest
{"elements":[
  {"id":"text.cta-label.0","where":"createNode:ctaLabel","how":"ctx.fontAtlas.createText renders BEGIN COMMISSION at 0.2 scene units"},
  {"id":"text.caption.1","where":"createNode:caption","how":"ctx.fontAtlas.createText renders NO DEPOSIT REQUIRED at 0.09 units"},
  {"id":"color.background","where":"createNode:backdropMat/bdBottom","how":"bdBottom uses colors.background in unlit vertical gradient"},
  {"id":"color.surface","where":"createNode:backdropMat/bdTop","how":"bdTop uses colors.surface in unlit vertical gradient"},
  {"id":"color.ink","where":"createNode:backdropMat vignette / shadowMat","how":"vignette mix and contact shadow tinted with colors.
